//@ts-check

'use strict';

const path = require('path');

/**
 * Customizes the webpack configuration generated by the SharePoint Framework Heft
 * toolchain.
 *
 * @param {import('webpack').Configuration} webpackConfiguration
 * @param {import('@rushstack/heft').IHeftTaskSession} taskSession
 * @param {import('@rushstack/heft').HeftConfiguration} heftConfiguration
 */
module.exports = function (webpackConfiguration, taskSession, heftConfiguration) {
  // When creating a production build...
  if (taskSession.parameters.production) {
    // Create a stats folder and put generated webpack stats within it.
    const { BundleAnalyzerPlugin } = require('webpack-bundle-analyzer');

    const lastDirName = path.basename(heftConfiguration.buildFolderPath);
    const dropPath = path.join(heftConfiguration.buildFolderPath, 'temp', 'stats');

    webpackConfiguration.plugins = webpackConfiguration.plugins || [];
    webpackConfiguration.plugins.push(
      new BundleAnalyzerPlugin({
        openAnalyzer: false,
        analyzerMode: 'static',
        reportFilename: path.join(dropPath, `${lastDirName}.stats.html`),
        generateStatsFile: true,
        statsFilename: path.join(dropPath, `${lastDirName}.stats.json`),
        logLevel: 'error'
      })
    );
  }
};
